type State={phase:string;session_id:string|null;transport:string;completed_captures:number;detail:string;last_error:string|null;last_capture:Metric|null;face_processing?:string;face_error?:string|null;last_face?:Face|null;last_recording?:Recording|null;recording_processing?:string};
