const emptyMood:MoodSnapshot={mood:"neutral",intensity:20,summary:"今天还没有记录心情",support:"说说此刻的感受，让 Topia 回应你。",transcript:"",model:"",analyzedAt:""};
function loadMood():MoodSnapshot{try{const value=JSON.parse(localStorage.getItem("realtopia.mood")??"null") as Partial<MoodSnapshot>|null;if(!value||!moodKinds.includes(value.mood as MoodKind))return {...emptyMood};const text=(input:unknown,fallback:string,max:number)=>typeof input==="string"?input.slice(0,max):fallback;return {mood:value.mood as MoodKind,intensity:Math.max(0,Math.min(100,Number(value.intensity)||0)),summary:text(value.summary,emptyMood.summary,60),support:text(value.support,emptyMood.support,90),transcript:text(value.transcript,"",4000),model:text(value.model,"",100),analyzedAt:text(value.analyzedAt,"",40)}}catch{return {...emptyMood}}}
