 document.querySelector("#start-asr-download")?.addEventListener("click",async()=>{try{await invoke("start_asr_download");toast("ASR 模型已加入系统下载队列");setTimeout(()=>void refreshModelDownload(true),500)}catch(error){toast(error instanceof Error?error.message:"ASR 下载启动失败")}});
